var INTL={"155_2":{"id":"155_2","guideline":"ESC 2024: хронические коронарные синдромы","org":"ESC","year":2024,"url":"https://doi.org/10.1093/eurheartj/ehae177","diffs":["Термин **хронический коронарный синдром (ХКС)** вместо «стабильной ИБС»; включает микрососудистую дисфункцию и вазоспазм (ANOCA/INOCA).","Предтестовая вероятность — по модели **RF-CL** (с учётом факторов риска), а не только по возрасту, полу и симптомам.","Антиангинальная терапия **подбирается индивидуально** (β-АБ и/или БКК, другие — по особенностям), жёсткой «первой и второй линии» нет.","Колхицин 0,5 мг — для снижения риска событий (IIa).","У больных СД 2 — иНГЛТ-2 и агонисты ГПП-1 с доказанной СС-пользой независимо от гликемии."],"classification":{"theses":["ХКС — спектр от стенокардии с обструктивным атеросклерозом до ANOCA/INOCA и ХСН ишемического генеза.","Профилактика событий — **у всех**: антиагрегант и статин до целевого ХС ЛНП."],"blocks":[{"type":"list","title":"Всем с ХКС","items":[{"label":"Антитромботическая терапия","go":{"title":"Антитромботическая терапия","g":["anti"],"n":3}},{"label":"Липиды и противовоспалительная терапия","go":{"title":"Липиды, колхицин","g":["lip"],"n":3}}]},{"type":"list","title":"Варианты ХКС","items":[{"label":"Стенокардия при обструктивном поражении","go":{"title":"Антиангинальная терапия","g":["angina"],"n":4}},{"label":"ANOCA/INOCA: микрососудистая стенокардия","go":{"title":"INOCA","g":["inoca"],"n":2}},{"label":"Вазоспастическая стенокардия","go":{"title":"INOCA","g":["inoca"],"n":2}},{"label":"После ОКС или реваскуляризации","go":{"title":"Антитромботическая терапия","g":["anti"],"n":3}}]}]},"diagnosis":["Оценка вероятности обструктивной ИБС по модели RF-CL; при низкой (≤ 5%) — поиск других причин.","Неинвазивная визуализация: КТ-коронарография при низкой/умеренной вероятности; функциональные тесты — при более высокой.","Инвазивная коронарография — при высокой вероятности, тяжёлых симптомах или высоком риске."],"treatment":[{"id":"anti","h":"Антитромботическая терапия","items":[{"t":"Аспирин пожизненно; клопидогрел — альтернатива.","cls":"I A","dose":"АСК 75–100 мг/сут; клопидогрел 75 мг/сут"},{"t":"После ЧКВ — ДАТТ обычно 6 месяцев (1–3 мес при высоком риске кровотечения), затем монотерапия.","cls":"I A"},{"t":"При ФП и ЧКВ — ОАК + клопидогрел до 6–12 мес, затем ОАК.","cls":"I"}]},{"id":"lip","h":"Липиды и воспаление","items":[{"t":"Статины высокой интенсивности; цель ХС ЛНП < 1,4 ммоль/л и снижение ≥ 50%.","cls":"I A","dose":"аторвастатин 40–80 мг; розувастатин 20–40 мг"},{"t":"Добавить эзетимиб, затем иPCSK9 при недостижении цели.","cls":"I B","dose":"эзетимиб 10 мг"},{"t":"Колхицин в низкой дозе.","cls":"IIa A","dose":"0,5 мг/сут"}]},{"id":"angina","h":"Антиангинальная терапия","items":[{"t":"Короткодействующие нитраты для купирования приступа.","cls":"I B","dose":"нитроглицерин 0,4–0,5 мг сублингвально"},{"t":"Начальная терапия: β-АБ и/или БКК — с учётом ЧСС, АД, ФВ и сопутствующих заболеваний.","cls":"I B","dose":"бисопролол 5–10 мг; амлодипин 5–10 мг"},{"t":"Добавочно: нитраты длительного действия, ранолазин, ивабрадин, никорандил, триметазидин — индивидуально.","cls":"IIa"},{"t":"Реваскуляризация — при сохранении симптомов на терапии или для улучшения прогноза (ствол, многососудистое поражение со сниженной ФВ).","cls":"I A"}]},{"id":"inoca","h":"ANOCA/INOCA","items":[{"t":"Микрососудистая стенокардия: β-АБ, БКК, иАПФ, статины.","cls":"IIa B"},{"t":"Вазоспастическая: БКК, нитраты; избегать β-АБ без БКК.","cls":"I"}]},{"id":"dm","h":"Сопутствующий СД 2 и ХСН","items":[{"t":"иНГЛТ-2 и/или агонисты ГПП-1 с доказанной СС-пользой.","cls":"I A"},{"t":"ХСН со сниженной ФВ — базовая терапия ХСН.","cls":"I"}]}],"exam":["ЭКГ покоя, ЭхоКГ","Липидный профиль, глюкоза/HbA1c, креатинин и СКФ, ОАК","КТ-коронарография или функциональная визуализация по предтестовой вероятности"],"followup":["Визит через 2–3 месяца после начала терапии, затем ежегодно","ХС ЛНП через 4–6 недель после изменения терапии","Кардиореабилитация, отказ от курения, вакцинация против гриппа"]},"156_2":{"id":"156_2","guideline":"ESC 2026: сердечная недостаточность","org":"ESC","year":2026,"url":"https://doi.org/10.1093/eurheartj/ehag100","diffs":["**ХСН с умеренно сниженной ФВ упразднена**: два фенотипа — сниженная ФВ (< 50%) и сохранённая (≥ 50%). В КР — три фенотипа с порогами 40 и 50%.","**Стадии A–D** (как в американских рекомендациях): A — риск, B — пре-ХСН, C — симптомная, D — далеко зашедшая. В КР — предстадия и стадии 1–2 (РКО 2023).","Вместо «оптимальной медикаментозной терапии» — **базовая (foundational) терапия**: при сниженной ФВ — β-АБ, иРААС (АРНИ/иАПФ/БРА), АМКР, иНГЛТ-2; при сохранённой — **АМКР и иНГЛТ-2**.","**АМКР — класс I при хронической ХСН независимо от ФВ** (в т. ч. финеренон при ФВ ≥ 40%).","Семаглутид или тирзепатид — класс IIa при сохранённой ФВ и ожирении.","«Острая» СН переименована в **декомпенсированную**; повышен класс дигоксина/дигитоксина, MitraClip и механической поддержки."],"classification":{"theses":["Диагноз ХСН — только при **симптомах и/или признаках**: одна ФВ без симптомов — не ХСН (стадия B).","Фенотип определяет базовую терапию: при сниженной ФВ — четыре группы, при сохранённой — две."],"blocks":[{"type":"scale","title":"Стадии","items":[{"label":"A · риск ХСН","crit":"АГ, СД, ожирение, ИБС, кардиотоксичность; без структурных изменений и повышения НУП","tone":0,"go":{"title":"Стадия A–B: профилактика","g":["prev"],"n":4}},{"label":"B · пре-ХСН","crit":"симптомов нет и не было; есть структурные или функциональные изменения сердца либо повышен НУП","tone":1,"go":{"title":"Стадия A–B: профилактика","g":["prev"],"n":4}},{"label":"C · симптомная ХСН","crit":"симптомы или признаки сейчас или в прошлом","tone":3,"jump":"phen"},{"label":"D · далеко зашедшая","crit":"тяжёлые симптомы и повторные события несмотря на оптимальную терапию","tone":4,"go":{"title":"Стадия D","g":["adv"],"n":2}}]},{"type":"tiles","id":"phen","title":"Фенотип при стадии C","items":[{"big":"< 50%","label":"Сниженная ФВ","crit":"4 группы базовой терапии","tone":4,"go":{"title":"ХСН со сниженной ФВ","g":["hfref","addref"],"n":10}},{"big":"≥ 50%","label":"Сохранённая ФВ","crit":"АМКР + иНГЛТ-2","tone":2,"go":{"title":"ХСН с сохранённой ФВ","g":["hfpef"],"n":3}}]}]},"diagnosis":["Симптомы и/или признаки + объективные изменения сердца (ЭхоКГ) и/или повышенный НУП.","НУП для исключения ХСН вне стационара: NT-proBNP < 125 пг/мл или BNP < 35 пг/мл (у пожилых, при ФП и ХБП пороги выше).","В диагнозе — стадия, фенотип по ФВ, этиология, ФК NYHA, декомпенсация."],"treatment":[{"id":"hfref","h":"Сниженная ФВ (< 50%): базовая терапия","items":[{"t":"Все четыре группы начинают как можно раньше, вплоть до одновременного старта; титрация каждые 1–2 недели.","cls":"I"},{"t":"β-АБ (бисопролол, карведилол, метопролола сукцинат, небиволол).","cls":"I","dose":"бисопролол 1,25 → 10 мг/сут; карведилол 3,125 → 25 мг × 2; метопролола сукцинат 12,5–25 → 200 мг/сут"},{"t":"иРААС: валсартан+сакубитрил (предпочтительно) или иАПФ; БРА — при непереносимости.","cls":"I","dose":"валсартан+сакубитрил 24/26–49/51 → 97/103 мг × 2; эналаприл 2,5 → 10–20 мг × 2; рамиприл 2,5 → 5 мг × 2"},{"t":"АМКР: спиронолактон или эплеренон; контроль калия и креатинина.","cls":"I","dose":"спиронолактон 25 → 50 мг/сут; эплеренон 25 → 50 мг/сут"},{"t":"иНГЛТ-2: дапаглифлозин или эмпаглифлозин, без титрации.","cls":"I","dose":"10 мг 1 раз в сутки"},{"t":"Петлевые диуретики — по застою, в минимальной эффективной дозе.","cls":"I","dose":"фуросемид 20–40 мг; торасемид 5–10 мг"}]},{"id":"addref","h":"Сниженная ФВ: дополнительная терапия","items":[{"t":"Ивабрадин — синусовый ритм, ЧСС ≥ 70 на максимально переносимом β-АБ.","dose":"5 → 7,5 мг × 2"},{"t":"Дигоксин — для контроля ЧСС при ФП или сохраняющихся симптомах (класс повышен).","dose":"0,0625–0,25 мг/сут, концентрация 0,5–0,9 нг/мл"},{"t":"Препараты железа внутривенно при ферритине < 100 или 100–299 мкг/л с насыщением трансферрина < 20%.","dose":"железа карбоксимальтозат или дериизомальтозат — по дефициту"},{"t":"Верицигуат — после недавней декомпенсации.","dose":"2,5 → 10 мг/сут"}]},{"id":"hfpef","h":"Сохранённая ФВ (≥ 50%)","items":[{"t":"Базовая терапия: **АМКР** (в т. ч. финеренон) + **иНГЛТ-2**.","cls":"I","dose":"дапаглифлозин или эмпаглифлозин 10 мг/сут; финеренон 10–20 → 20–40 мг/сут (по СКФ); спиронолактон 25–50 мг/сут"},{"t":"Диуретики при застое; лечение АГ, ФП, ишемии."},{"t":"Ожирение: семаглутид или тирзепатид.","cls":"IIa","dose":"семаглутид до 2,4 мг 1 раз в неделю; тирзепатид до 15 мг 1 раз в неделю"}]},{"id":"prev","h":"Стадии A–B: профилактика","items":[{"t":"Контроль АД, отказ от курения, снижение веса, физическая активность."},{"t":"СД 2 с ССЗ или высоким риском — иНГЛТ-2; ХБП с СД 2 — финеренон."},{"t":"СД 2 и ещё один фактор СС-риска — агонисты ГПП-1.","cls":"IIa A"},{"t":"Бессимптомная дисфункция ЛЖ (ФВ ≤ 40%), после ИМ — иАПФ и β-АБ."}]},{"id":"adv","h":"Стадия D","items":[{"t":"Ранняя консультация в центре ХСН: трансплантация, механическая поддержка (LVAD — класс I у отобранных)."},{"t":"Паллиативная помощь — при неэффективности."}]}],"exam":["NT-proBNP или BNP","ЭКГ, ЭхоКГ","ОАК, креатинин и СКФ, калий, натрий, глюкоза или HbA1c, липиды, ТТГ","Ферритин и насыщение трансферрина","Рентгенография грудной клетки — для поиска других причин одышки"],"followup":["При титрации — визит каждые 1–2 недели с контролем АД, ЧСС, калия, креатинина","Стабильным — каждые 3–6 месяцев; ЭхоКГ через 3–6 месяцев после оптимизации терапии","Обучение самоконтролю: ежедневный вес, симптомы декомпенсации, приверженность","Вакцинация против гриппа, пневмококка, COVID-19; кардиореабилитация"]},"273_5":{"id":"273_5","guideline":"ACG 2020: хронический панкреатит; AGA 2023: экзокринная недостаточность","org":"ACG/AGA","year":2023,"url":"https://doi.org/10.14309/ajg.0000000000000535","diffs":["Диагноз — прежде всего **КТ или МРТ/МРХПГ**; ЭУС — при неоднозначных данных; функциональные тесты — вспомогательные.","Экзокринная недостаточность: **фекальная эластаза < 100 мкг/г** — высоко вероятна, 100–200 — неоднозначно; ферменты — по клинике и тесту.","Стартовая доза ферментов указана явно: **≥ 40 000–50 000 ЕД липазы на основной приём пищи**, половина — на перекус (AGA 2023).","Ферменты **не назначают для купирования боли** без экзокринной недостаточности.","Ежегодный скрининг **панкреатогенного СД (тип 3c)**, оценка минеральной плотности кости и жирорастворимых витаминов."],"classification":{"theses":["Классификация TIGAR-O — по этиологии: токсико-метаболическая, идиопатическая, генетическая, аутоиммунная, рецидивирующий острый, обструктивная.","Ведение определяют **осложнения**: боль, экзокринная и эндокринная недостаточность, стриктуры, псевдокисты."],"blocks":[{"type":"list","title":"Этиология (TIGAR-O)","items":[{"label":"Токсико-метаболическая","crit":"алкоголь, курение, гиперкальциемия, гипертриглицеридемия, ХБП","go":{"title":"Устранение причины","g":["cause"],"n":1}},{"label":"Аутоиммунная","crit":"IgG4-связанный и тип 2","go":{"title":"Аутоиммунный панкреатит","g":["aip"],"n":1}},{"label":"Генетическая, обструктивная, идиопатическая"}]},{"type":"list","title":"Осложнения","items":[{"label":"Боль","go":{"title":"Боль","g":["pain"],"n":3}},{"label":"Экзокринная недостаточность","crit":"стеаторея, похудание, дефицит витаминов","go":{"title":"Заместительная ферментная терапия","g":["pert"],"n":3}},{"label":"Панкреатогенный СД (3c)","go":{"title":"СД 3c","g":["dm"],"n":1}}]}]},"diagnosis":["КТ или МРТ с МРХПГ — первая линия; ЭУС — если неинформативно.","Фекальная эластаза-1 при подозрении на экзокринную недостаточность.","IgG4 при подозрении на аутоиммунный панкреатит."],"treatment":[{"id":"cause","h":"Устранение причины","items":[{"t":"Полный отказ от алкоголя и курения — замедляет прогрессирование и уменьшает боль."}]},{"id":"pain","h":"Боль","items":[{"t":"Ступенчатая анальгезия: парацетамол, НПВС, затем слабые опиоиды; прегабалин — адъювант.","dose":"прегабалин 75–300 мг × 2"},{"t":"Ферменты и антиоксиданты для лечения боли рутинно не назначают."},{"t":"При обструкции протока — эндоскопическое лечение или ранняя хирургия (хирургия эффективнее при длительной боли)."}]},{"id":"pert","h":"Заместительная ферментная терапия","items":[{"t":"Панкреатин в микросферах во время еды.","dose":"40 000–50 000 ЕД липазы на основной приём пищи, 20 000–25 000 — на перекус; увеличивать при неэффективности"},{"t":"Если эффект недостаточный — добавить ИПП, проверить СИБР и другие причины диареи."},{"t":"Диета без жёсткого ограничения жиров; восполнение витаминов A, D, E, K."}]},{"id":"dm","h":"Панкреатогенный СД","items":[{"t":"Ежегодно глюкоза натощак и HbA1c; при СД — метформин или инсулин; избегать гипогликемий."}]},{"id":"aip","h":"Аутоиммунный панкреатит","items":[{"t":"Глюкокортикоиды — индукция ремиссии; при рецидивах — иммуносупрессоры, ритуксимаб.","dose":"преднизолон 0,6–1 мг/кг/сут (обычно 40 мг) 2–4 недели, затем снижение"}]}],"exam":["КТ или МРТ/МРХПГ","Фекальная эластаза","Глюкоза натощак, HbA1c","25(OH)D, витамины A, E, ферритин, альбумин","DXA — исходно"],"followup":["Ежегодно: вес, симптомы мальабсорбции, HbA1c, витамины","DXA каждые 2 года при остеопении","Онкологическая настороженность: рост риска рака поджелудочной железы, особенно при наследственных формах"]},"277_2":{"id":"277_2","guideline":"ACG 2024 (H. pylori) и Маастрихт VI 2022: язвенная болезнь","org":"ACG/Maastricht","year":2024,"url":"https://doi.org/10.14309/ajg.0000000000002968","diffs":["Эрадикация — **висмутовая квадротерапия 14 дней** как предпочтительная эмпирическая схема; кларитромициновую тройную терапию эмпирически не используют (ACG 2024).","Вонопразан + амоксициллин (двойная) или + амоксициллин + кларитромицин — опции у пациентов без подтверждённой резистентности.","**Контроль эрадикации обязателен у всех** — тестом через ≥ 4 недели.","НПВС-язва: отменить НПВС; если отмена невозможна — ИПП постоянно, по возможности ЦОГ-2-селективный препарат."],"classification":{"theses":["Главное — **причина**: H. pylori, НПВС/аспирин, обе, или идиопатическая.","Желудочная язва требует биопсии и эндоскопического контроля заживления."],"blocks":[{"type":"tiles","title":"Причина","items":[{"big":"Hp+","label":"H. pylori","tone":3,"go":{"title":"Эрадикация","g":["erad"],"n":3}},{"big":"НПВС","label":"лекарственная","tone":3,"go":{"title":"НПВС-язва","g":["nsaid"],"n":2}},{"big":"?","label":"идиопатическая","crit":"исключить скрытый приём НПВС, гастриному, Крона","tone":2,"go":{"title":"Заживление язвы","g":["heal"],"n":1}}]}]},"diagnosis":["ЭГДС; биопсия краёв желудочной язвы.","H. pylori — биопсия (уреазный тест, гистология) или неинвазивные тесты; при кровотечении ложноотрицательные результаты — повторить."],"treatment":[{"id":"erad","h":"Эрадикация H. pylori","items":[{"t":"Висмутовая квадротерапия 14 дней.","dose":"ИПП × 2 + висмута субцитрат 120 мг × 4 + тетрациклин 500 мг × 4 + метронидазол 500 мг × 3–4"},{"t":"При известной чувствительности — схемы по тесту; вонопразан-содержащие — по доступности.","dose":"вонопразан 20 мг × 2 + амоксициллин 1000 мг × 3, 14 дней"},{"t":"После эрадикации при неосложнённой дуоденальной язве продолжение ИПП не обязательно; при желудочной или осложнённой — ИПП 4–8 недель."}]},{"id":"nsaid","h":"НПВС-язва","items":[{"t":"Отменить НПВС; ИПП 8 недель.","dose":"омепразол 20–40 мг/сут или эквивалент"},{"t":"Если НПВС нужны — ЦОГ-2-селективный + ИПП; аспирин для профилактики ССЗ — продолжать с ИПП."}]},{"id":"heal","h":"Заживление язвы","items":[{"t":"ИПП в стандартной дозе 4 недели (дуоденальная) — 8 недель (желудочная).","dose":"омепразол 20 мг, пантопразол 40 мг, эзомепразол 20–40 мг 1–2 раза в сутки"}]}],"exam":["ЭГДС с биопсией","Тест на H. pylori","ОАК, ферритин при кровопотере"],"followup":["Контроль эрадикации через ≥ 4 недели после лечения, ИПП отменить за 2 недели","Желудочная язва — контрольная ЭГДС через 8–12 недель для подтверждения заживления и исключения рака"]},"290_2":{"id":"290_2","guideline":"ADA Standards of Care in Diabetes — 2026","org":"ADA","year":2026,"url":"https://diabetesjournals.org/care/issue/49/Supplement_1","diffs":["Выбор препарата — **по сопутствующим заболеваниям, а не только по HbA1c**: иНГЛТ-2 и агонисты ГПП-1 при АССЗ, ХСН, ХБП — независимо от метформина и HbA1c.","**ГПП-1 и ГИП/ГПП-1 (тирзепатид)** — предпочтительны для снижения веса; при ХСН с сохранённой ФВ и ожирении; при СКФ < 30 — предпочтительный сахароснижающий препарат.","Комбинированная терапия раньше — при HbA1c ≥ 7,5% или кардиоренометаболических заболеваниях.","Если нужна инъекционная терапия — агонисты ГПП-1 предпочтительнее инсулина.","**НМГ (CGM)** — рекомендован всем подходящим пациентам с СД, в т. ч. СД 2 без инсулина.","Тяжесть и «компенсацию» в диагноз не выносят; цель HbA1c — индивидуальная (обычно < 7%)."],"classification":{"theses":["Типы: СД 1 (с доклиническими стадиями 1–2 по аутоантителам), СД 2, особые типы, гестационный.","При СД 2 решающее значение имеют **кардиоренальные коморбидности** и вес."],"blocks":[{"type":"list","title":"Выбор препарата при СД 2","items":[{"label":"АССЗ или высокий СС-риск","go":{"title":"АССЗ","g":["cv"],"n":2}},{"label":"ХСН","go":{"title":"ХСН","g":["hf"],"n":3}},{"label":"ХБП","go":{"title":"ХБП","g":["ckd"],"n":4}},{"label":"Ожирение, МАЖБП","go":{"title":"Вес и печень","g":["wt"],"n":3}},{"label":"Цель — гликемия без коморбидностей","go":{"title":"Гликемический контроль","g":["gly"],"n":4}}]}]},"diagnosis":["HbA1c ≥ 6,5%, глюкоза натощак ≥ 7,0 ммоль/л, через 2 ч ОГТТ ≥ 11,1 или случайная ≥ 11,1 при симптомах; без симптомов — подтверждение повторным тестом.","Предиабет: HbA1c 5,7–6,4%, глюкоза натощак 5,6–6,9 ммоль/л.","Скрининг СД 2 — всем с 35 лет и раньше при избыточном весе и факторах риска."],"treatment":[{"id":"cv","h":"АССЗ или высокий СС-риск","items":[{"t":"Агонист ГПП-1 и/или иНГЛТ-2 с доказанной СС-пользой — независимо от HbA1c и метформина.","cls":"A","dose":"семаглутид п/к 0,25 → 1–2 мг/нед или перорально 3 → 14 мг/сут; лираглутид 0,6 → 1,8 мг/сут; дулаглутид 0,75–4,5 мг/нед; эмпаглифлозин или дапаглифлозин 10 мг"},{"t":"Тирзепатид — с доказанной СС-пользой в сравнении с дулаглутидом.","dose":"2,5 → до 15 мг 1 раз в неделю"}]},{"id":"hf","h":"ХСН","items":[{"t":"иНГЛТ-2 — при ХСН с любой ФВ.","cls":"A","dose":"10 мг/сут"},{"t":"ХСН с сохранённой ФВ и ожирение — семаглутид или тирзепатид для уменьшения симптомов и событий.","cls":"A"},{"t":"Нестероидный АМКР (финеренон) — для снижения ухудшений ХСН."}]},{"id":"ckd","h":"ХБП","items":[{"t":"иНГЛТ-2 при СКФ ≥ 20 — независимо от HbA1c.","cls":"A"},{"t":"Финеренон при альбуминурии ≥ 30 мг/г на иАПФ/БРА; при альбуминурии ≥ 100 мг/г и СКФ 30–90 можно начать одновременно с иНГЛТ-2.","cls":"A","dose":"10–20 мг/сут"},{"t":"Агонисты ГПП-1 — для снижения почечных и СС-событий; при СКФ < 30 — предпочтительный сахароснижающий препарат, в т. ч. на диализе.","cls":"B"},{"t":"Метформин — при СКФ ≥ 30 (снизить дозу при 30–44).","dose":"до 1000 мг/сут при СКФ 30–44"}]},{"id":"wt","h":"Ожирение и МАЖБП","items":[{"t":"Агонисты ГПП-1 или ГИП/ГПП-1 — предпочтительны для снижения веса; дозы и титрация — индивидуально.","cls":"A"},{"t":"МАЖБП/МАСГ — агонисты ГПП-1 или ГИП/ГПП-1 с доказанной пользой для печени; пиоглитазон — альтернатива."},{"t":"Метаболическая хирургия — при ИМТ ≥ 30 (≥ 27,5 у азиатов) по показаниям."}]},{"id":"gly","h":"Гликемический контроль","items":[{"t":"Метформин — первая линия при отсутствии противопоказаний.","dose":"500 мг → 2000 мг/сут, пролонгированный — 1 раз"},{"t":"Добавлять препараты с учётом эффективности, веса, гипогликемий, стоимости; комбинации раньше при HbA1c ≥ 7,5%."},{"t":"Инсулин — при HbA1c > 10% или глюкозе ≥ 16,7 ммоль/л с симптомами, при катаболизме.","dose":"базальный 10 ЕД или 0,1–0,2 ЕД/кг, титрация каждые 3 дня по глюкозе натощак"},{"t":"Цели: HbA1c < 7% для большинства; время в диапазоне 3,9–10 ммоль/л > 70% по НМГ; мягче у пожилых и при риске гипогликемий."}]}],"exam":["HbA1c, липидный профиль, креатинин и СКФ, альбумин/креатинин мочи, АЛТ/АСТ, ОАК","FIB-4 — для скрининга фиброза печени","Осмотр глазного дна, стоп (монофиламент), АД, вес и окружность талии","Скрининг депрессии и нарушения пищевого поведения"],"followup":["HbA1c каждые 3 месяца до цели, затем 2 раза в год","Альбуминурия и СКФ — ежегодно (чаще при ХБП)","Офтальмолог — ежегодно (раз в 1–2 года без ретинопатии)","Стопы — ежегодно, при высоком риске — каждый визит; липиды — ежегодно"]},"359_3":{"id":"359_3","guideline":"GINA 2026: глобальная стратегия по бронхиальной астме","org":"GINA","year":2026,"url":"https://ginasthma.org/reports/","diffs":["**Трек 1 (предпочтительный)**: низкие дозы ИГКС-формотерола **по потребности** на ступенях 1–2 и как **поддерживающая и купирующая терапия (MART)** с 3-й ступени. В КР — ИГКС-формотерол по потребности при лёгкой БА как одна из опций.","**КДБА без ИГКС не применяется ни на одной ступени**; в треке 2 на ступени 1 добавлен ингалятор ИГКС-КДБА.","ИГКС-формотерол — опция при лёгком обострении в первичном звене и в неотложной помощи.","Диагноз подтверждают **до начала ИГКС**: после старта терапии объективно подтвердить астму сложнее; критерий «ОФВ₁ > 10% от должного» отменён.","Новые биологические препараты при тяжёлой БА: депемокимаб, биоаналог омализумаба."],"classification":{"theses":["Контроль — по **симптомам за 4 недели** и **риску обострений**; тяжесть — ретроспективно по ступени, на которой достигнут контроль.","Шаг вверх — только после проверки техники ингаляции, приверженности, триггеров и коморбидности."],"blocks":[{"type":"scale","title":"Ступени (взрослые и подростки)","items":[{"label":"Ступени 1–2","crit":"лёгкая БА: ИГКС-формотерол по потребности","tone":1,"go":{"title":"Ступени 1–2","g":["s12"],"n":2}},{"label":"Ступень 3","crit":"MART низкими дозами ИГКС-формотерола","tone":2,"go":{"title":"Ступень 3","g":["s34"],"n":3}},{"label":"Ступень 4","crit":"MART средними дозами","tone":3,"go":{"title":"Ступень 4","g":["s34"],"n":3}},{"label":"Ступень 5","crit":"+ ДДАХ, оценка фенотипа, биологическая терапия","tone":4,"go":{"title":"Ступень 5 и тяжёлая БА","g":["s5"],"n":3}}]},{"type":"list","title":"Обострение","items":[{"label":"Лёгкое и среднетяжёлое в первичном звене","go":{"title":"Обострение","g":["exac"],"n":3}}]}]},"diagnosis":["Типичные вариабельные симптомы + подтверждённая вариабельная обструкция: прирост ОФВ₁ ≥ 12% и ≥ 200 мл после бронхолитика, вариабельность ПСВ, прирост ОФВ₁ после 4 недель ИГКС или положительная провокационная проба.","FeNO и эозинофилы — для оценки Т2-воспаления, не для исключения астмы."],"treatment":[{"id":"s12","h":"Ступени 1–2 (трек 1)","items":[{"t":"Низкие дозы ИГКС-формотерола по потребности (AIR).","dose":"будесонид/формотерол 160/4,5 мкг (доставленная доза) — 1 ингаляция по потребности, до 12 ингаляций в сутки"},{"t":"Трек 2: КДБА + ИГКС при каждом использовании КДБА (или ингалятор ИГКС-КДБА); на ступени 2 — регулярно низкие дозы ИГКС."}]},{"id":"s34","h":"Ступени 3–4: MART","items":[{"t":"Ступень 3 — MART низкими дозами: поддерживающая доза ежедневно + по потребности тем же ингалятором.","dose":"будесонид/формотерол 160/4,5 мкг: 1 ингаляция × 2 + по потребности (до 12 в сутки)"},{"t":"Ступень 4 — MART средними дозами.","dose":"будесонид/формотерол 160/4,5 мкг: 2 ингаляции × 2 + по потребности"},{"t":"Трек 2: ИГКС-ДДБА в низких/средних дозах + КДБА или ИГКС-КДБА по потребности."}]},{"id":"s5","h":"Ступень 5 и тяжёлая БА","items":[{"t":"Добавить ДДАХ (тиотропий) к ИГКС-ДДБА.","dose":"тиотропий Респимат 2,5 мкг × 2 ингаляции 1 раз в сутки"},{"t":"Направить к специалисту для фенотипирования; биологическая терапия: анти-IgE, анти-IL-5/5R, анти-IL-4R, анти-TSLP, депемокимаб."},{"t":"Азитромицин — у отдельных взрослых с персистирующими симптомами; поддерживающие пероральные ГКС — крайняя мера."}]},{"id":"exac","h":"Обострение в первичном звене","items":[{"t":"Лёгкое: ИГКС-формотерол или КДБА; увеличить ИГКС-формотерол по плану действий."},{"t":"Среднетяжёлое: КДБА (или ИГКС-формотерол), контролируемая подача кислорода (SpO₂ 93–96%), пероральные ГКС.","dose":"преднизолон 40–50 мг/сут 5–7 дней"},{"t":"Признаки тяжёлого или жизнеугрожающего обострения — срочная госпитализация."}]}],"exam":["Спирометрия с бронхолитиком (до начала ИГКС, если возможно)","ПСВ-мониторинг при неясности","Эозинофилы крови, FeNO, общий IgE, аллергообследование — по показаниям","Оценка коморбидности: ринит, ожирение, ГЭРБ, тревога/депрессия"],"followup":["Через 1–3 месяца после начала или изменения терапии, затем каждые 3–12 месяцев","Каждый визит: контроль симптомов, обострения, техника ингаляции, приверженность, письменный план действий","Спирометрия — через 3–6 месяцев после начала лечения, далее периодически","При стабильном контроле ≥ 3 месяцев — обсудить снижение дозы"]},"382_2":{"id":"382_2","guideline":"ESC 2024: фибрилляция предсердий","org":"ESC","year":2024,"url":"https://doi.org/10.1093/eurheartj/ehae176","diffs":["Риск инсульта — по **CHA₂DS₂-VA**: женский пол больше не даёт балл. ОАК рекомендованы при ≥ 2 баллах, рассматриваются при 1. В КР — CHA₂DS₂-VASc с порогами по полу.","Шкалы кровотечения (HAS-BLED) — только для поиска модифицируемых факторов, **не для отказа от ОАК**.","Подход **AF-CARE**: лечение коморбидности (АГ, ожирение, апноэ, алкоголь) — отдельный обязательный компонент.","Ранний контроль ритма рассматривается у всех подходящих пациентов в первые 12 месяцев после диагноза.","Катетерная аблация — первая линия при пароксизмальной ФП у отобранных пациентов."],"classification":{"theses":["Форму ФП определяют по течению; от неё зависит стратегия контроля ритма, но **не показания к ОАК**.","Профилактика инсульта — по CHA₂DS₂-VA при любой форме."],"blocks":[{"type":"list","title":"При любой форме","items":[{"label":"Антикоагулянты по CHA₂DS₂-VA","crit":"≥ 2 — рекомендованы, 1 — рассмотреть","go":{"title":"Профилактика инсульта","g":["oac"],"n":5}}]},{"type":"scale","title":"Форма ФП","items":[{"label":"Впервые диагностированная","tone":1},{"label":"Пароксизмальная","crit":"проходит сама или после кардиоверсии в течение 7 дней","tone":2,"go":{"title":"Контроль ритма","g":["rhythm"],"n":4}},{"label":"Персистирующая","crit":"> 7 дней","tone":3,"go":{"title":"Контроль ритма","g":["rhythm"],"n":4}},{"label":"Длительно персистирующая","crit":"≥ 12 месяцев при выборе контроля ритма","tone":3,"go":{"title":"Контроль ритма","g":["rhythm"],"n":4}},{"label":"Постоянная","crit":"решено не восстанавливать ритм","tone":4,"go":{"title":"Контроль частоты","g":["rate"],"n":2}}]}]},"diagnosis":["ЭКГ-документация: ≥ 30 с ФП на одноканальной записи или 12-канальная ЭКГ.","В диагнозе — форма, симптомы (шкала EHRA), CHA₂DS₂-VA, сопутствующие заболевания."],"treatment":[{"id":"oac","h":"Профилактика инсульта (A — антикоагуляция)","items":[{"t":"CHA₂DS₂-VA ≥ 2 — ОАК; = 1 — рассмотреть.","cls":"I C / IIa C"},{"t":"ПОАК предпочтительнее варфарина (кроме механических клапанов и умеренного/тяжёлого митрального стеноза).","cls":"I A","dose":"апиксабан 5 мг × 2; ривароксабан 20 мг/сут; эдоксабан 60 мг/сут; дабигатран 150 мг × 2 — снижение доз по критериям инструкции"},{"t":"Не снижать дозу ПОАК без критериев.","cls":"III B"},{"t":"Антиагреганты как альтернатива ОАК не рекомендованы.","cls":"III A"},{"t":"Окклюзия ушка ЛП — при противопоказаниях к длительной ОАК.","cls":"IIb C"}]},{"id":"rate","h":"Контроль частоты (R)","items":[{"t":"β-АБ, дилтиазем или верапамил (только при ФВ > 40%), дигоксин; комбинации при недостаточном эффекте.","cls":"I B","dose":"бисопролол 1,25–20 мг/сут; метопролол 50–200 мг/сут; дилтиазем 60 мг × 3 — 360 мг/сут; верапамил 40 мг × 2 — 480 мг/сут; дигоксин 0,0625–0,25 мг/сут"},{"t":"Мягкий контроль: ЧСС в покое < 110 — начальная цель.","cls":"IIa B"}]},{"id":"rhythm","h":"Контроль ритма (E — оценка, R)","items":[{"t":"Контроль ритма — для уменьшения симптомов; ранний (в первые 12 мес) — для снижения риска событий у подходящих пациентов.","cls":"I A / IIa B"},{"t":"Антиаритмики по структуре сердца: амиодарон — при любой, флекаинид/пропафенон — без значимой структурной патологии.","cls":"I","dose":"амиодарон 200 мг/сут поддерживающая; пропафенон 150–300 мг × 3"},{"t":"Катетерная аблация — первая линия при пароксизмальной ФП; после неэффективности ААП — при пароксизмальной и персистирующей.","cls":"I A"},{"t":"Кардиоверсия при ФП > 24 ч — после ≥ 3 недель ОАК или ЧПЭхоКГ; ОАК ≥ 4 недель после.","cls":"I B"}]},{"id":"comorb","h":"Коморбидность и факторы риска (C)","items":[{"t":"Контроль АД, снижение веса ≥ 10% при ожирении, лечение апноэ, отказ от алкоголя, физическая активность.","cls":"I"},{"t":"ХСН — иНГЛТ-2 и базовая терапия; СД — контроль гликемии.","cls":"I"}]}],"exam":["12-канальная ЭКГ, ЭхоКГ (ТТЭ)","ОАК, креатинин и КК, печёночные пробы, ТТГ, глюкоза/HbA1c, электролиты","Холтер/длительный мониторинг — при подозрении на пароксизмы и для контроля ЧСС"],"followup":["Пересматривать CHA₂DS₂-VA и факторы кровотечения на каждом визите","КК, печень и ОАК на ПОАК — ежегодно; при КК < 60 и у пожилых чаще","Ежегодно: симптомы, ЭКГ, приверженность, коморбидность (AF-CARE)"]},"469_3":{"id":"469_3","guideline":"KDIGO 2024: оценка и лечение ХБП","org":"KDIGO","year":2024,"url":"https://doi.org/10.1016/j.kint.2023.10.018","diffs":["Стадии те же (СКФ G1–G5 × альбуминурия A1–A3), но прогноз — по **«тепловой карте»** риска; для направления к нефрологу — **калькулятор KFRE** (5-летний риск ТПН ≥ 3–5%).","СКФ — по креатинину, а при сомнениях — **по креатинину и цистатину C** (eGFRcr-cys); формула CKD-EPI 2021 без расового коэффициента.","**иНГЛТ-2 при СКФ ≥ 20**: при СД 2, при альбуминурии ≥ 200 мг/г, при ХСН; рассматриваются и при СКФ 20–45 с меньшей альбуминурией.","**Финеренон** — при СД 2, СКФ > 25, нормальном калии и альбуминурии ≥ 30 мг/г на иАПФ/БРА; агонисты ГПП-1 — при СД 2 для снижения СС-риска.","Целевое САД **< 120 мм рт. ст.** при стандартизованном измерении, если переносится.","Аллопуринол/фебуксостат при бессимптомной гиперурикемии для замедления ХБП **не рекомендуются**."],"classification":{"theses":["ХБП — изменения структуры или функции почек > 3 месяцев: СКФ < 60 и/или альбуминурия ≥ 30 мг/г или другие маркёры.","Классификация **CGA**: причина + категория СКФ + альбуминурия."],"blocks":[{"type":"scale","title":"Категории СКФ","sub":"мл/мин/1,73 м²","items":[{"label":"G1–G2","crit":"≥ 60 (ХБП — только при маркёрах повреждения)","tone":0,"go":{"title":"Базовая ренопротекция","g":["base","drugs"],"n":10}},{"label":"G3a","crit":"45–59","tone":2,"go":{"title":"G3: ренопротекция и осложнения","g":["drugs","compl"],"n":9}},{"label":"G3b","crit":"30–44","tone":3,"go":{"title":"G3b","g":["drugs","compl"],"n":9}},{"label":"G4","crit":"15–29","tone":4,"go":{"title":"G4: подготовка к ЗПТ","g":["drugs","compl","ref"],"n":11}},{"label":"G5","crit":"< 15","tone":4,"go":{"title":"G5","g":["ref"],"n":2}}]},{"type":"scale","title":"Альбуминурия","sub":"альбумин/креатинин мочи","items":[{"label":"A1","crit":"< 30 мг/г (< 3 мг/ммоль)","tone":0},{"label":"A2","crit":"30–300 мг/г (3–30 мг/ммоль)","tone":2,"go":{"title":"Альбуминурия: иАПФ/БРА, иНГЛТ-2, финеренон","g":["drugs"],"n":5}},{"label":"A3","crit":"> 300 мг/г (> 30 мг/ммоль)","tone":4,"go":{"title":"A3","g":["drugs","ref"],"n":7}}]}]},"diagnosis":["Подтвердить хроничность: повторить СКФ и альбумин/креатинин через 3 месяца.","Установить причину: анамнез, анализ мочи, УЗИ почек, при необходимости — биопсия.","Оценить риск ТПН по KFRE при СКФ < 60."],"treatment":[{"id":"base","h":"Всем с ХБП","items":[{"t":"Отказ от курения, физическая активность ≥ 150 мин в неделю, нормальный вес.","cls":"1D"},{"t":"Натрий < 2 г/сут (соль < 5 г); белок 0,8 г/кг/сут при G3–G5 без диализа.","cls":"2C"},{"t":"Статин (± эзетимиб) — всем взрослым ≥ 50 лет с ХБП без диализа; < 50 лет — при факторах риска.","cls":"1A","dose":"аторвастатин 20 мг; розувастатин 10 мг; при G3–G5 избегать высоких доз розувастатина"},{"t":"Целевое САД < 120 мм рт. ст., если переносится.","cls":"2B"},{"t":"Избегать НПВС; корректировать дозы препаратов по СКФ."}]},{"id":"drugs","h":"Ренопротекция","items":[{"t":"иАПФ или БРА в максимально переносимой дозе: при A2–A3 и СД; при A3 без СД.","cls":"1B","dose":"напр. рамиприл 2,5 → 10 мг; лозартан 50 → 100 мг; валсартан 80 → 320 мг"},{"t":"иНГЛТ-2: СД 2 и СКФ ≥ 20; альбуминурия ≥ 200 мг/г; ХСН — независимо от альбуминурии. Продолжать до диализа.","cls":"1A","dose":"дапаглифлозин 10 мг; эмпаглифлозин 10 мг"},{"t":"Финеренон: СД 2, СКФ > 25, K⁺ норма, альбуминурия ≥ 30 мг/г на иАПФ/БРА.","cls":"2A","dose":"СКФ 25–59: 10 мг → 20 мг; СКФ ≥ 60: 20 мг/сут"},{"t":"Агонисты ГПП-1 при СД 2, если не достигнута цель гликемии на метформине и иНГЛТ-2 или они противопоказаны.","cls":"1B","dose":"напр. семаглутид 0,25 → 1 мг 1 раз в неделю"},{"t":"Нельзя сочетать иАПФ, БРА и прямой ингибитор ренина.","cls":"1B"}]},{"id":"compl","h":"Осложнения","items":[{"t":"Гиперкалиемия — не отменять иАПФ/БРА сразу: диета, диуретики, калийсвязывающие препараты."},{"t":"Метаболический ацидоз (бикарбонат < 18) — пероральный бикарбонат натрия."},{"t":"Анемия — исключить дефицит железа; ЭСС — по показаниям у нефролога."},{"t":"Бессимптомную гиперурикемию не лечить для замедления ХБП; при подагре — уратснижающая терапия.","cls":"1D"}]},{"id":"ref","h":"Направление к нефрологу","items":[{"t":"5-летний риск ТПН по KFRE ≥ 3–5%; СКФ < 30; альбуминурия ≥ 300 мг/г; быстрое снижение СКФ; эритроцитурия неясного генеза; резистентная АГ; гиперкалиемия.","cls":"1A"},{"t":"Подготовка к ЗПТ — при 2-летнем риске ТПН > 40% (KFRE)."}]}],"exam":["СКФ (CKD-EPI 2021) по креатинину; цистатин C — при сомнениях","Альбумин/креатинин в утренней моче","Общий анализ мочи с осадком","УЗИ почек","Калий, бикарбонат, ОАК, кальций, фосфор, ПТГ (G3b–G5), липиды, HbA1c"],"followup":["Частота контроля СКФ и альбуминурии — по тепловой карте: от 1 раза в год (G1–G2 A1) до 4 и более раз в год (G4–G5, A3)","Креатинин и калий через 2–4 недели после старта или увеличения дозы иАПФ/БРА/финеренона; прирост креатинина до 30% допустим","Пересчитывать KFRE при каждом контроле СКФ < 60"]},"603_3":{"id":"603_3","guideline":"GOLD 2026: глобальная стратегия по ХОБЛ","org":"GOLD","year":2026,"url":"https://goldcopd.org/2026-gold-report-and-pocket-guide/","diffs":["**Группа E — уже при одном среднетяжёлом или тяжёлом обострении** за год (раньше и в КР — ≥ 2 среднетяжёлых или ≥ 1 с госпитализацией).","Новые понятия: **стабильность** и **контроль** заболевания — низкая активность без обострений как цель.","Разделены алгоритмы **стартовой** терапии (по группе) и **последующей** (по одышке и обострениям, независимо от группы).","Биологическая терапия: **дупилумаб и меполизумаб** при обострениях на тройной терапии и эозинофилах ≥ 300.","При сохраняющейся одышке на ДДБА/ДДАХ — можно добавить **энсифентрин**; азитромицин — предпочтительно у бывших курильщиков."],"classification":{"theses":["Стартовая терапия — по группе **A, B, E**; спирометрическая степень GOLD 1–4 — для прогноза.","Эозинофилы крови — биомаркер для назначения ИГКС."],"blocks":[{"type":"matrix","title":"Группа (GOLD 2026)","rows":["≥ 1 среднетяжёлое или тяжёлое обострение","0 обострений"],"cols":["mMRC 0–1, CAT < 10","mMRC ≥ 2, CAT ≥ 10"],"cells":[[{"label":"E","span":2,"tone":4,"crit":"ДДБА + ДДАХ; ± ИГКС при эоз. ≥ 300","go":{"title":"Группа E","g":["init"],"n":4}}],[{"label":"A","tone":1,"crit":"один бронходилататор","go":{"title":"Группа A","g":["init"],"n":4}},{"label":"B","tone":2,"crit":"ДДБА + ДДАХ","go":{"title":"Группа B","g":["init"],"n":4}}]]},{"type":"list","title":"Уже на поддерживающей терапии","items":[{"label":"Сохраняется одышка","go":{"title":"Одышка на терапии","g":["fu_dysp"],"n":2}},{"label":"Продолжаются обострения","go":{"title":"Обострения на терапии","g":["fu_exac"],"n":5}}]}]},"diagnosis":["Постбронходилатационное ОФВ₁/ФЖЕЛ < 0,7 при симптомах и факторах риска.","Оценка: симптомы (mMRC, CAT), обострения за год, эозинофилы, коморбидность.","Скрининг ХОБЛ у курильщиков и в программах скрининга рака лёгкого."],"treatment":[{"id":"init","h":"Стартовая терапия по группе","items":[{"t":"A — один бронходилататор (предпочтительно длительного действия).","dose":"тиотропий 18 мкг (ингалятор) или 5 мкг (Респимат) 1 раз в сутки; индакатерол 150–300 мкг 1 раз"},{"t":"B — ДДБА + ДДАХ, лучше в одном ингаляторе.","dose":"напр. тиотропий/олодатерол 5/5 мкг 1 раз; гликопиррония/индакатерол 50/110 мкг 1 раз"},{"t":"E — ДДБА + ДДАХ; ДДБА + ДДАХ + ИГКС, если эозинофилы ≥ 300 кл/мкл. ДДБА + ИГКС без ДДАХ не рекомендуется."},{"t":"Всем — КДБА по потребности, отказ от курения, вакцинация, реабилитация."}]},{"id":"fu_dysp","h":"Последующая терапия: одышка","items":[{"t":"Монотерапия → ДДБА + ДДАХ.","dose":""},{"t":"На ДДБА + ДДАХ: сменить ингалятор или молекулу, исключить другие причины одышки, рассмотреть энсифентрин; реабилитация."}]},{"id":"fu_exac","h":"Последующая терапия: обострения","items":[{"t":"Монотерапия → ДДБА + ДДАХ; при эозинофилах ≥ 300 — сразу тройная терапия.","dose":""},{"t":"На ДДБА + ДДАХ: эоз. ≥ 100 — добавить ИГКС (тройная терапия, лучше один ингалятор).","dose":"напр. флутиказона фуроат/умеклидиний/вилантерол 92/55/22 мкг 1 раз; будесонид/гликопирроний/формотерол 160/7,2/5 мкг × 2"},{"t":"На тройной терапии и эоз. ≥ 300 — дупилумаб или меполизумаб.","dose":"дупилумаб 300 мг п/к раз в 2 недели; меполизумаб 100 мг п/к раз в 4 недели"},{"t":"Эоз. < 100 или без эффекта: рофлумиласт (ОФВ₁ < 50%, хронический бронхит) или азитромицин (предпочтительно у бывших курильщиков).","dose":"рофлумиласт 500 мкг/сут; азитромицин 250 мг/сут или 500 мг 3 раза в неделю"},{"t":"Отмена ИГКС — при пневмонии или отсутствии эффекта; при эоз. ≥ 300 риск обострения после отмены выше."}]},{"id":"exac","h":"Лечение обострения","items":[{"t":"КДБА ± короткодействующий антихолинергик — начальные бронходилататоры.","dose":"сальбутамол 100–200 мкг (через спейсер) или небулайзер 2,5 мг"},{"t":"Системные ГКС 5 дней.","dose":"преднизолон 40 мг/сут"},{"t":"Антибиотики — при гнойной мокроте и усилении одышки/объёма мокроты, 5–7 дней."}]}],"exam":["Спирометрия с бронхолитиком","Эозинофилы крови","SpO₂; газы крови при SpO₂ < 88%","Рентгенография или КТ грудной клетки; КТ — при подозрении на эмфизему, бронхоэктазы, рак","α1-антитрипсин — однократно, особенно в зонах высокой распространённости","Оценка коморбидности: ССЗ, остеопороз, тревога и депрессия"],"followup":["Каждый визит: симптомы (CAT/mMRC), обострения, техника ингаляции, приверженность, курение","Спирометрия — ежегодно","Вакцинация: грипп, пневмококк, COVID-19, RSV (≥ 60 лет), Tdap, опоясывающий лишай"]},"617_5":{"id":"617_5","guideline":"NICE NG97 (2018, обновления): деменция","org":"NICE","year":2018,"url":"https://www.nice.org.uk/guidance/ng97","diffs":["Для когнитивного скрининга — **короткие валидированные тесты** (10-CS, 6CIT, Mini-Cog и др.); результат не заменяет оценку специалиста.","**Ингибиторы ХЭ и мемантин** — по типу и тяжести деменции; при **УКР** и **лобно-височной деменции** не назначают.","При сосудистой деменции противодементные препараты — только при смешанной деменции с болезнью Альцгеймера, с тельцами Леви или Паркинсона.","Антипсихотики — **только** при риске вреда или тяжёлом дистрессе, минимальная доза, пересмотр через 6 недель.","Анти-амилоидные антитела (леканемаб, донанемаб) в NHS не рекомендованы (оценка NICE 2025)."],"classification":{"theses":["Тип деменции определяет лечение: Альцгеймер, сосудистая, с тельцами Леви, лобно-височная, смешанная.","УКР — не деменция: противодементные препараты не назначают."],"blocks":[{"type":"list","title":"Тип деменции → лечение","items":[{"label":"Болезнь Альцгеймера","go":{"title":"Болезнь Альцгеймера","g":["ad"],"n":2}},{"label":"С тельцами Леви","go":{"title":"Деменция с тельцами Леви","g":["dlb"],"n":2}},{"label":"Сосудистая","crit":"лечение факторов риска; противодементные — только при смешанной","go":{"title":"Сосудистая","g":["vad"],"n":2}},{"label":"Лобно-височная","crit":"ингибиторы ХЭ и мемантин не назначают"},{"label":"Поведенческие и психотические симптомы","go":{"title":"Нарушения поведения","g":["bpsd"],"n":3}}]}]},"diagnosis":["Анамнез от пациента и родственника, когнитивный тест, исключение делирия и депрессии.","Анализы: ОАК, мочевина и электролиты, кальций, HbA1c, печёночные пробы, ТТГ, B12, фолаты.","Структурная визуализация (КТ/МРТ) — для исключения других причин и уточнения типа; направление к специалисту по памяти."],"treatment":[{"id":"ad","h":"Болезнь Альцгеймера","items":[{"t":"Лёгкая и умеренная: донепезил, галантамин или ривастигмин.","dose":"донепезил 5 → 10 мг/сут; галантамин 8 → 16–24 мг/сут; ривастигмин пластырь 4,6 → 9,5 мг/24 ч"},{"t":"Умеренная при непереносимости ингибиторов ХЭ или тяжёлая — мемантин; при умеренной/тяжёлой на ингибиторе ХЭ — рассмотреть добавление мемантина.","dose":"мемантин 5 мг → 20 мг/сут (по 5 мг в неделю)"}]},{"id":"dlb","h":"Деменция с тельцами Леви","items":[{"t":"Донепезил или ривастигмин (лёгкая и умеренная); галантамин — при непереносимости; мемантин — при непереносимости ингибиторов ХЭ."},{"t":"Избегать типичных антипсихотиков — тяжёлые реакции."}]},{"id":"vad","h":"Сосудистая деменция","items":[{"t":"Контроль АД, липидов, СД, антитромботическая терапия по показаниям."},{"t":"Ингибиторы ХЭ и мемантин — только при смешанной деменции."}]},{"id":"bpsd","h":"Нарушения поведения","items":[{"t":"Сначала — поиск причин (боль, делирий, запор, инфекция) и немедикаментозные методы."},{"t":"Антипсихотик — только при риске вреда или тяжёлом дистрессе; минимальная доза, пересмотр через 6 недель.","dose":"напр. рисперидон 0,25–1 мг/сут"},{"t":"Антидепрессанты при ажитации не назначать (если нет депрессии)."}]}],"exam":["Короткий когнитивный тест","ОАК, электролиты, кальций, HbA1c, печёночные пробы, ТТГ, B12, фолаты","КТ или МРТ головного мозга","Пересмотр лекарств с антихолинергической нагрузкой"],"followup":["Регулярная оценка когнитивного статуса, повседневной активности, безопасности и нагрузки на ухаживающих","Пересмотр противодементной терапии на эффект и переносимость","Планирование помощи и предварительные распоряжения"]},"62_3":{"id":"62_3","guideline":"ESC 2024: повышенное АД и артериальная гипертензия","org":"ESC","year":2024,"url":"https://doi.org/10.1093/eurheartj/ehae178","diffs":["Новая категория **«повышенное АД»** 120–139/70–89 мм рт. ст.; деления АГ на 1–3 степени нет.","Целевое САД на лечении — **120–129 мм рт. ст.** для большинства, включая пожилых без астении до 85 лет; при плохой переносимости — «настолько низкое, насколько разумно достижимо» (ALARA). В КР — поэтапно < 140/90, затем < 130/80.","При повышенном АД 130–139 мм рт. ст. и высоком риске (SCORE2 ≥ 10%, ССЗ, СД, ХБП, ПОМ) — **лекарства после 3 месяцев** изменения образа жизни.","Впервые рекомендована **ренальная денервация** при резистентной АГ (в опытных центрах, СКФ ≥ 40).","Больше акцента на СМАД и самоконтроль АД дома; добавки калия — при отсутствии ХБП."],"classification":{"theses":["Три категории офисного АД: **не повышенное**, **повышенное**, **гипертензия**.","Решение о лечении при повышенном АД — по 10-летнему риску SCORE2 и состояниям высокого риска."],"blocks":[{"type":"scale","title":"Категории АД","sub":"офисное АД, мм рт. ст.","items":[{"label":"Не повышенное","crit":"< 120 / < 70","tone":0},{"label":"Повышенное","crit":"120–139 / 70–89","tone":2,"go":{"title":"Повышенное АД","g":["elev"],"n":2}},{"label":"Гипертензия","crit":"≥ 140 / ≥ 90","tone":4,"go":{"title":"Гипертензия: старт и ступени","g":["start","steps"],"n":7}}]},{"type":"list","title":"Высокий риск при повышенном АД","items":[{"label":"SCORE2 / SCORE2-OP ≥ 10%","calc":"score2"},{"label":"ССЗ, СД, ХБП умеренная и тяжёлая, СГХС, ПОМ"}]}]},"diagnosis":["Гипертензию подтверждают **внеофисным АД** (СМАД: среднесуточное ≥ 130/80; домашнее ≥ 135/85) или повторными офисными измерениями.","Скрининг вторичной АГ — у молодых (< 40 лет), при резистентной АГ, гипокалиемии, внезапном начале; первичный гиперальдостеронизм — альдостерон-рениновое соотношение."],"treatment":[{"id":"elev","h":"Повышенное АД (120–139/70–89)","items":[{"t":"Всем — изменение образа жизни: снижение соли, ≥ 150 мин умеренной аэробной нагрузки в неделю, снижение веса, отказ от курения, алкоголь — меньше.","cls":"I"},{"t":"САД ≥ 130 через 3 месяца и высокий риск — начать лекарственную терапию.","cls":"I A"}]},{"id":"start","h":"Старт при гипертензии","items":[{"t":"Лекарства + образ жизни сразу при АД ≥ 140/90.","cls":"I A"},{"t":"Стартовая **двойная комбинация в низких дозах, лучше в одной таблетке**: иАПФ или БРА + дигидропиридиновый БКК или тиазидоподобный диуретик.","cls":"I B","dose":"напр. периндоприл 4–5 мг + амлодипин 5 мг; лозартан 50 мг + гидрохлоротиазид 12,5 мг"},{"t":"Монотерапия в низкой дозе — при АД 120–139 и высоком риске, астении, ортостатической гипотензии, ≥ 85 лет.","cls":"IIa"}]},{"id":"steps","h":"Если не достигнута цель","items":[{"t":"Тройная комбинация: иАПФ/БРА + БКК + диуретик, лучше одной таблеткой.","cls":"I A","dose":"напр. периндоприл + индапамид + амлодипин"},{"t":"Резистентная АГ — добавить **спиронолактон**; при непереносимости — эплеренон, β-АБ, α-АБ, клонидин.","cls":"IIa B","dose":"спиронолактон 25–50 мг/сут"},{"t":"Ренальная денервация — при неконтролируемой АГ на трёх препаратах, СКФ ≥ 40, по желанию пациента, в опытном центре.","cls":"IIb B"},{"t":"β-АБ — при особых показаниях (стенокардия, после ИМ, ХСН, контроль ЧСС).","cls":"I"}]},{"id":"special","h":"Сопутствующие состояния","items":[{"t":"ХБП с альбуминурией и СД 2 — иАПФ/БРА; иНГЛТ-2 при СКФ ≥ 20.","cls":"I A"},{"t":"Статины — по общему СС-риску; антиагреганты в первичной профилактике не рекомендованы.","cls":"III"},{"t":"Нельзя сочетать иАПФ и БРА.","cls":"III A"}]}],"exam":["Офисное АД на обеих руках, СМАД или домашнее АД","Креатинин и СКФ, отношение альбумин/креатинин мочи, калий, натрий","Глюкоза или HbA1c, липидный профиль","ЭКГ (12 отведений); ЭхоКГ — при изменениях ЭКГ или симптомах","Оценка SCORE2 у лиц без ССЗ"],"followup":["После начала или изменения терапии — визит через 1 месяц, далее каждые 3 месяца до достижения цели","Затем — не реже 1 раза в год: АД, приверженность, СКФ, калий, альбуминурия","Поощрять домашний контроль АД"]},"654_2":{"id":"654_2","guideline":"ATS/IDSA 2019 + обновление ATS 2025: внебольничная пневмония","org":"ATS/IDSA","year":2025,"url":"https://doi.org/10.1164/rccm.202507-1692ST","diffs":["Длительность АБТ: амбулаторно и при нетяжёлой ВП в стационаре — **менее 5 дней (минимум 3)** после достижения клинической стабильности; при тяжёлой — ≥ 5 дней.","Здоровым амбулаторным пациентам с **положительным тестом на респираторный вирус** эмпирические антибиотики обычно не нужны.","Системные ГКС **рекомендуются при тяжёлой ВП** (кроме гриппозной пневмонии) и **не рекомендуются при нетяжёлой**.","**УЗИ лёгких** — приемлемая альтернатива рентгенографии для диагностики.","Макролид в монотерапии — только при резистентности пневмококка к макролидам < 25% (в России обычно выше); место лечения — по PSI (предпочтительнее CURB-65)."],"classification":{"theses":["Выбор антибиотика — по **месту лечения** (амбулаторно / стационар / ОРИТ), **коморбидности** и факторам риска MRSA и синегнойной палочки.","Тяжёлая ВП — 1 большой или ≥ 3 малых критериев ATS/IDSA."],"blocks":[{"type":"list","title":"Амбулаторно","items":[{"label":"Без сопутствующих заболеваний","go":{"title":"Амбулаторно, без коморбидности","g":["out0"],"n":2}},{"label":"С сопутствующими заболеваниями","crit":"ХСН, ХБП, ХОБЛ, СД, алкоголизм, онкология, аспления","go":{"title":"Амбулаторно, с коморбидностью","g":["out1"],"n":2}}]},{"type":"list","title":"Стационар","items":[{"label":"Нетяжёлая","go":{"title":"Стационар, нетяжёлая ВП","g":["inp"],"n":2}},{"label":"Тяжёлая","crit":"большие: септический шок, ИВЛ; малые: ЧДД ≥ 30, PaO₂/FiO₂ ≤ 250, мультилобарная, спутанность, мочевина ≥ 7 ммоль/л, лейкоциты < 4, тромбоциты < 100, t < 36 °C, гипотензия, требующая инфузии","go":{"title":"Тяжёлая ВП","g":["sev"],"n":3}}]}]},"diagnosis":["Клиника + инфильтрат на рентгенограмме или УЗИ лёгких.","Тяжесть и место лечения — по PSI (предпочтительно) и клинической оценке.","Посевы крови и мокроты — при тяжёлой ВП и факторах риска MRSA/синегнойной палочки; тест на грипп и SARS-CoV-2 в сезон.","Прокальцитонин не используют для решения о старте антибиотика."],"treatment":[{"id":"out0","h":"Амбулаторно, без сопутствующих заболеваний","items":[{"t":"Амоксициллин, или доксициклин, или макролид (если резистентность < 25%).","dose":"амоксициллин 1 г × 3; доксициклин 100 мг × 2; азитромицин 500 мг в 1-й день, далее 250 мг; кларитромицин 500 мг × 2"},{"t":"Длительность — < 5 дней (минимум 3) после клинической стабилизации."}]},{"id":"out1","h":"Амбулаторно, с сопутствующими заболеваниями","items":[{"t":"Амоксициллин/клавуланат или цефалоспорин + макролид или доксициклин.","dose":"амоксициллин/клавуланат 875/125 мг × 2 или 2000/125 мг × 2; цефуроксим 500 мг × 2; цефподоксим 200 мг × 2"},{"t":"Или респираторный фторхинолон в монотерапии.","dose":"левофлоксацин 750 мг/сут; моксифлоксацин 400 мг/сут"}]},{"id":"inp","h":"Стационар, нетяжёлая ВП","items":[{"t":"β-лактам + макролид или респираторный фторхинолон.","dose":"ампициллин/сульбактам 1,5–3 г × 4; цефтриаксон 1–2 г/сут; цефотаксим 1–2 г × 3 + азитромицин 500 мг/сут"},{"t":"Системные ГКС не назначать.","cls":"сильная"}]},{"id":"sev","h":"Тяжёлая ВП","items":[{"t":"β-лактам + макролид или β-лактам + респираторный фторхинолон; при факторах риска — покрытие MRSA и синегнойной палочки.","dose":"ванкомицин или линезолид — MRSA; пиперациллин/тазобактам 4,5 г × 4, цефепим 2 г × 3 — синегнойная палочка"},{"t":"Системные ГКС (кроме гриппозной пневмонии).","cls":"условная","dose":"напр. гидрокортизон 200 мг/сут"},{"t":"Длительность ≥ 5 дней."}]}],"exam":["Рентгенография или УЗИ лёгких","SpO₂, ОАК, креатинин, мочевина, электролиты, глюкоза","Тест на грипп/SARS-CoV-2 в сезон","При тяжёлой ВП — посевы крови и мокроты, антигены пневмококка и легионеллы в моче, лактат"],"followup":["Оценка клинической стабильности на 2–3-й день: t, ЧСС, ЧДД, АД, SpO₂, способность есть, сознание","Контрольная рентгенография — не рутинно; при сохранении симптомов или у курильщиков старше 50 лет — через 6–8 недель","Вакцинация против пневмококка и гриппа"]},"655_2":{"id":"655_2","guideline":"ERS 2020: хронический кашель; ACCP/CHEST: хронический бронхит","org":"ERS/CHEST","year":2020,"url":"https://doi.org/10.1183/13993003.01136-2019","diffs":["«Хронический бронхит» без обструкции — по международным подходам часть **синдрома хронического кашля**: продуктивный кашель ≥ 3 месяцев 2 года подряд при исключении других причин.","Обязательно — **спирометрия** (исключить ХОБЛ и астму) и поиск причин: курение, ИАПФ, ГЭРБ, риносинусит, бронхоэктазы.","Обострения: антибиотики — при гнойной мокроте и усилении симптомов; при остром бронхите у здоровых — **не назначать**.","При резистентном хроническом кашле — **низкодозовый морфин** или габапентин; при продуктивном кашле без эффекта от лечения — пробный курс макролида (ERS, условно)."],"classification":{"theses":["Хронический кашель — > 8 недель.","Хронический бронхит — продуктивный кашель ≥ 3 месяцев в году ≥ 2 лет; с обструкцией — ХОБЛ."],"blocks":[{"type":"list","title":"Тактика","items":[{"label":"Курящий, без обструкции","go":{"title":"Отказ от курения","g":["smoke"],"n":2}},{"label":"Обострение","go":{"title":"Обострение","g":["exac"],"n":2}},{"label":"Рефрактерный хронический кашель","go":{"title":"Рефрактерный кашель","g":["refr"],"n":4}}]}]},"diagnosis":["Спирометрия с бронхолитиком; при сомнениях — FeNO, эозинофилы.","Рентгенография грудной клетки; КТ — при подозрении на бронхоэктазы.","Оценить ИАПФ, курение, ГЭРБ, риносинусит, ночной кашель."],"treatment":[{"id":"smoke","h":"Курение и триггеры","items":[{"t":"Отказ от курения — наиболее эффективная мера: кашель уменьшается у большинства в течение месяцев.","dose":"варениклин 0,5 → 1 мг × 2 12 недель; никотинзаместительная терапия"},{"t":"Отменить ИАПФ при кашле."}]},{"id":"exac","h":"Обострение","items":[{"t":"Короткодействующие бронходилататоры при одышке.","dose":"ипратропий/фенотерол 1–2 ингаляции до 4 раз в сутки"},{"t":"Антибиотик — при гнойной мокроте и усилении симптомов.","dose":"амоксициллин 500 мг × 3 или доксициклин 100 мг × 2, 5–7 дней"}]},{"id":"refr","h":"Рефрактерный хронический кашель","items":[{"t":"Пробный курс ИГКС при эозинофильном воспалении; лечение ГЭРБ при её признаках."},{"t":"Низкодозовый морфин пролонгированного действия.","cls":"условная","dose":"морфин 5–10 мг × 2"},{"t":"Габапентин.","cls":"условная","dose":"300 → до 1800 мг/сут"},{"t":"Продуктивный кашель без эффекта — пробный курс макролида.","cls":"условная","dose":"азитромицин 250 мг 3 раза в неделю"}]}],"exam":["Спирометрия","Рентгенография грудной клетки","ОАК (эозинофилы)","КТ — по показаниям"],"followup":["Оценка через 4–8 недель после отказа от курения или курса лечения","Спирометрия ежегодно у курящих с хроническим кашлем — для раннего выявления ХОБЛ"]},"708_2":{"id":"708_2","guideline":"Маастрихт VI / Флорентийский консенсус 2022: H. pylori","org":"Maastricht VI","year":2022,"url":"https://doi.org/10.1136/gutjnl-2022-327745","diffs":["H. pylori-гастрит — **инфекционное заболевание**, эрадикация показана всем инфицированным независимо от симптомов.","Стратегия **«тестируй и лечи»** при диспепсии без тревожных симптомов.","Выбор схемы — по чувствительности (тест на резистентность) или по региональной резистентности к кларитромицину; при > 15% или неизвестной — **висмутовая квадротерапия 14 дней** первой линией.","Стадирование атрофии **OLGA/OLGIM** с биопсиями по Сиднейской системе; эндоскопический контроль каждые 3 года при OLGA/OLGIM III–IV.","Вонопразан-содержащие схемы и высокодозная двойная терапия (ИПП + амоксициллин) — новые опции."],"classification":{"theses":["Этиологическая классификация (Киото) — основа: лечение определяет причина.","Стадия атрофии (OLGA/OLGIM) определяет онкологический риск и наблюдение."],"blocks":[{"type":"list","title":"Этиология","items":[{"label":"H. pylori-ассоциированный","go":{"title":"Эрадикация","g":["erad"],"n":4}},{"label":"Лекарственный (НПВС, аспирин)","go":{"title":"НПВС","g":["nsaid"],"n":2}},{"label":"Аутоиммунный","crit":"B12-дефицит, риск НЭО желудка"}]},{"type":"scale","title":"Атрофия (OLGA/OLGIM)","items":[{"label":"Стадия 0–II","crit":"низкий риск","tone":1},{"label":"Стадия III–IV","crit":"высокий риск рака желудка — эндоскопия каждые 3 года","tone":4,"go":{"title":"Наблюдение при атрофии","g":["surv"],"n":2}}]}]},"diagnosis":["Неинвазивно: дыхательный уреазный тест или антиген H. pylori в кале (моноклональный).","Отменить ИПП за 2 недели, антибиотики и висмут — за 4 недели до теста.","ЭГДС с биопсией (Сиднейская система, 5 фрагментов) — при тревожных симптомах, у пожилых и в группах риска рака."],"treatment":[{"id":"erad","h":"Эрадикация H. pylori","items":[{"t":"Висмутовая квадротерапия 14 дней — первая линия при резистентности к кларитромицину > 15% или неизвестной.","dose":"ИПП в стандартной дозе × 2 + висмута субцитрат 120 мг × 4 (или 240 мг × 2) + тетрациклин 500 мг × 4 + метронидазол 400–500 мг × 3–4"},{"t":"Тройная терапия с кларитромицином 14 дней — только при подтверждённой чувствительности или резистентности < 15%.","dose":"ИПП × 2 + кларитромицин 500 мг × 2 + амоксициллин 1000 мг × 2"},{"t":"Вторая линия: схемы с левофлоксацином (после квадротерапии) или висмутовая квадротерапия (после тройной).","dose":"левофлоксацин 500 мг/сут + амоксициллин 1000 мг × 2 + ИПП × 2, 14 дней"},{"t":"Высокодозная двойная терапия — опция.","dose":"ИПП в высокой дозе × 3–4 + амоксициллин ≥ 3 г/сут в 3–4 приёма, 14 дней"}]},{"id":"nsaid","h":"Лекарственный гастрит","items":[{"t":"Перед длительным приёмом НПВС или аспирина у лиц с язвенным анамнезом — тест и эрадикация H. pylori."},{"t":"ИПП для гастропротекции при факторах риска."}]},{"id":"surv","h":"Атрофия и метаплазия","items":[{"t":"OLGA/OLGIM III–IV — эндоскопия высокого разрешения каждые 3 года; при семейном анамнезе рака — чаще."},{"t":"Эрадикация при атрофии снижает риск рака, но не отменяет наблюдение."}]}],"exam":["Дыхательный уреазный тест или антиген в кале","ЭГДС с биопсией по показаниям","При аутоиммунном гастрите — B12, ферритин, антитела к париетальным клеткам"],"followup":["Контроль эрадикации — всем, не ранее 4 недель после окончания терапии (ИПП отменить за 2 недели)","Эндоскопический контроль — по стадии атрофии"]},"711_2":{"id":"711_2","guideline":"ACG 2024: алкогольная болезнь печени","org":"ACG","year":2024,"url":"https://doi.org/10.14309/ajg.0000000000002572","diffs":["**Лечение расстройства употребления алкоголя** — часть лечения АБП: фармакотерапия, психосоциальная помощь, совместно с наркологом.","Скрининг употребления — **AUDIT-C** (или AUDIT) у всех пациентов с заболеваниями печени.","Тяжёлый алкогольный гепатит: **MELD > 20** — преднизолон 28 дней с оценкой ответа по **шкале Лилля на 7-й день** (> 0,45 — прекратить).","Ранняя трансплантация печени — у отобранных пациентов с тяжёлым гепатитом без ответа на ГКС.","Фиброз — FIB-4 и эластография."],"classification":{"theses":["Спектр: стеатоз → стеатогепатит → фиброз и цирроз; **алкогольный гепатит** — клинический синдром с желтухой.","Тяжесть гепатита — по MELD (> 20 — тяжёлый)."],"blocks":[{"type":"scale","title":"Форма","items":[{"label":"Стеатоз","crit":"обратим при отказе от алкоголя","tone":1,"go":{"title":"Отказ от алкоголя","g":["aud"],"n":4}},{"label":"Алкогольный гепатит, MELD ≤ 20","tone":3,"go":{"title":"Нетяжёлый гепатит","g":["aud","nut"],"n":5}},{"label":"Алкогольный гепатит, MELD > 20","tone":4,"go":{"title":"Тяжёлый гепатит","g":["sah","nut"],"n":4}},{"label":"Цирроз","tone":4,"go":{"title":"Цирроз","g":["aud"],"n":4}}]}]},"diagnosis":["AUDIT-C/AUDIT; биомаркеры употребления (фосфатидилэтанол) — по возможности.","Алкогольный гепатит: желтуха < 8 недель, билирубин > 3 мг/дл, АСТ > 50, АСТ/АЛТ > 1,5, обе < 400, злоупотребление алкоголем.","FIB-4, эластография; исключить другие причины."],"treatment":[{"id":"aud","h":"Лечение расстройства употребления алкоголя","items":[{"t":"Полный отказ от алкоголя; психосоциальные методы (мотивационное консультирование, КПТ)."},{"t":"Без цирроза: налтрексон, акампросат; при циррозе — баклофен или акампросат (налтрексон — избегать при декомпенсации).","dose":"акампросат 666 мг × 3; баклофен 10 мг × 3 → до 30 мг × 3; налтрексон 50 мг/сут"},{"t":"Габапентин, топирамат — альтернативы.","dose":"габапентин 300–600 мг × 3; топирамат 25 → 150 мг/сут"},{"t":"Дисульфирам при заболеваниях печени не применять."}]},{"id":"sah","h":"Тяжёлый алкогольный гепатит (MELD > 20)","items":[{"t":"Преднизолон 28 дней при отсутствии инфекции, кровотечения, ОПП; шкала Лилля на 7-й день.","dose":"преднизолон 40 мг/сут"},{"t":"Скрининг инфекций до старта; оценка на раннюю трансплантацию."},{"t":"Пентоксифиллин не рекомендован."}]},{"id":"nut","h":"Питание","items":[{"t":"Энергия 35–40 ккал/кг, белок 1,2–1,5 г/кг; поздний вечерний перекус; тиамин.","dose":"тиамин 100 мг/сут (в/в при риске энцефалопатии Вернике)"}]}],"exam":["AUDIT-C","Печёночные пробы, МНО, альбумин, креатинин, ОАК — MELD","FIB-4, эластография","УЗИ брюшной полости"],"followup":["Регулярная оценка употребления (опрос, биомаркеры)","При циррозе — скрининг ГЦК и варикоза как при циррозе","Совместное ведение с наркологом"]},"715_2":{"id":"715_2","guideline":"Baveno VII 2022, EASL 2018 (декомпенсированный цирроз), AASLD 2021 (асцит)","org":"Baveno/EASL/AASLD","year":2022,"url":"https://doi.org/10.1016/j.jhep.2021.12.022","diffs":["Понятие **компенсированной хронической болезни печени (cACLD)** по эластографии: < 10 кПа — исключает, > 15 кПа — высоко вероятна; **клинически значимая портальная гипертензия** — жёсткость ≥ 25 кПа.","**Неселективные β-АБ (карведилол предпочтительно)** при КЗПГ — для **профилактики декомпенсации**, а не только кровотечения.","Скрининговую ЭГДС можно не делать при жёсткости < 20 кПа и тромбоцитах > 150 × 10⁹/л.","Ключевые точки прогноза — переход от компенсированной к декомпенсированной стадии; рекомпенсация после устранения причины.","Асцит: ограничение натрия 80–120 ммоль/сут (соль 4,6–6,9 г), а не строгая бессолевая диета."],"classification":{"theses":["Стадии: **компенсированная** (± КЗПГ) → **декомпенсированная** (асцит, кровотечение из варикоза, энцефалопатия).","Тяжесть — Чайлд–Пью и MELD; лечение — по осложнению."],"blocks":[{"type":"scale","title":"Стадия","items":[{"label":"cACLD без КЗПГ","crit":"жёсткость 10–15 кПа","tone":1,"go":{"title":"Этиологическое лечение","g":["etio"],"n":2}},{"label":"cACLD с КЗПГ","crit":"жёсткость ≥ 25 кПа или варикоз","tone":3,"go":{"title":"Профилактика декомпенсации","g":["etio","nsbb"],"n":4}},{"label":"Декомпенсированный цирроз","crit":"асцит, кровотечение, энцефалопатия","tone":4,"jump":"dec"}]},{"type":"list","id":"dec","title":"Осложнения","items":[{"label":"Асцит","go":{"title":"Асцит","g":["asc"],"n":3}},{"label":"Печёночная энцефалопатия","go":{"title":"ПЭ","g":["he"],"n":1}},{"label":"СБП, ГРС-ОПП","go":{"title":"Инфекции и ГРС","g":["sbp"],"n":3}}]}]},"diagnosis":["Транзиентная эластография + тромбоциты; при ≥ 25 кПа — КЗПГ.","УЗИ брюшной полости ± АФП — скрининг ГЦК каждые 6 месяцев.","Диагностический парацентез при любом новом асците и госпитализации: нейтрофилы ≥ 250/мм³ — СБП."],"treatment":[{"id":"etio","h":"Этиологическое лечение","items":[{"t":"Отказ от алкоголя, противовирусная терапия ВГВ/ВГС, снижение веса при МАЖБП — может привести к рекомпенсации."},{"t":"Статины при компенсированном циррозе — можно рассматривать (снижают риск декомпенсации)."}]},{"id":"nsbb","h":"КЗПГ: профилактика декомпенсации","items":[{"t":"Карведилол предпочтителен; альтернативы — пропранолол, надолол.","dose":"карведилол 6,25 мг → 12,5 мг/сут; пропранолол 20–40 мг × 2 до ЧСС 55–60"},{"t":"При противопоказаниях к β-АБ и крупном варикозе — эндоскопическое лигирование."}]},{"id":"asc","h":"Асцит","items":[{"t":"Ограничение натрия 80–120 ммоль/сут; спиронолактон, при рецидивах — + фуросемид.","dose":"спиронолактон 100 → до 400 мг/сут; фуросемид 40 → до 160 мг/сут"},{"t":"Напряжённый асцит — объёмный парацентез; при > 5 л — альбумин.","dose":"альбумин 8 г на каждый литр удалённой жидкости"},{"t":"Длительное введение альбумина при асците — по возможности (EASL)."}]},{"id":"he","h":"Печёночная энцефалопатия","items":[{"t":"Лактулоза — лечение и вторичная профилактика; рифаксимин — при рецидиве на лактулозе.","dose":"лактулоза 25 мл каждые 1–2 ч до стула, далее до 2–3 мягких стулов в сутки; рифаксимин 550 мг × 2"}]},{"id":"sbp","h":"Инфекции и ГРС","items":[{"t":"СБП — цефалоспорин III поколения + альбумин.","dose":"цефотаксим 2 г × 3; альбумин 1,5 г/кг в 1-й день и 1 г/кг на 3-й"},{"t":"Вторичная профилактика СБП — норфлоксацин или ципрофлоксацин.","dose":"норфлоксацин 400 мг/сут"},{"t":"ГРС-ОПП — терлипрессин + альбумин (в стационаре).","dose":"терлипрессин 1 мг каждые 4–6 ч или инфузия 2 мг/сут"}]}],"exam":["Эластография, тромбоциты","Билирубин, альбумин, МНО, креатинин, натрий — Чайлд–Пью и MELD","УЗИ ± АФП","ЭГДС — если жёсткость ≥ 20 кПа или тромбоциты ≤ 150"],"followup":["УЗИ ± АФП каждые 6 месяцев","Эластография ежегодно при компенсированной стадии","Направление в трансплантационный центр: MELD ≥ 15 или декомпенсация","Вакцинация против ВГА, ВГВ, пневмококка, гриппа"]},"752_1":{"id":"752_1","guideline":"ESC/EAS 2019 + фокусное обновление 2025: дислипидемии","org":"ESC/EAS","year":2025,"url":"https://doi.org/10.1093/eurheartj/ehaf190","diffs":["Риск у лиц без ССЗ и СД — по **SCORE2 (40–69) и SCORE2-OP (70–89)**; целевые ХС ЛНП не изменились.","**Лп(а) > 50 мг/дл (105 нмоль/л)** — фактор, повышающий риск (IIa); вч-СРБ > 2 мг/л и коронарный кальций — модификаторы риска.","Новый препарат — **бемпедоевая кислота**: при непереносимости статинов (I) и как добавка к статину ± эзетимибу (IIa).","При ОКС — интенсивная, в т. ч. **комбинированная** гиполипидемическая терапия уже в индексную госпитализацию («раньше и ниже»).","Икозапент этил 2 г × 2 — при высоком риске и ТГ 1,5–5,6 ммоль/л на статине; БАДы не рекомендованы."],"classification":{"theses":["Цель лечения — **ХС ЛНП по категории риска**; категории те же, что в 2019 г.","Без ССЗ и СД риск считают по SCORE2/SCORE2-OP."],"blocks":[{"type":"scale","title":"Категория риска → цель ХС ЛНП","items":[{"label":"Очень высокий","crit":"ССЗ, СД с ПОМ, ХБП СКФ < 30, SCORE2 высокий для возраста; < 1,4 ммоль/л и снижение ≥ 50%","tone":4,"go":{"title":"Очень высокий риск","g":["start","add"],"n":6}},{"label":"Высокий","crit":"ХС ЛНП > 4,9, СГХС без ССЗ, ХБП СКФ 30–59; < 1,8 и снижение ≥ 50%","tone":3,"go":{"title":"Высокий риск","g":["start","add"],"n":6}},{"label":"Умеренный","crit":"< 2,6 ммоль/л","tone":2,"calc":"score2"},{"label":"Низкий","crit":"< 3,0 ммоль/л","tone":0,"calc":"score2"}]},{"type":"list","title":"Особые ситуации","items":[{"label":"ОКС","go":{"title":"ОКС","g":["acs"],"n":2}},{"label":"Гипертриглицеридемия","go":{"title":"Триглицериды","g":["tg"],"n":3}}]}]},"diagnosis":["Липидный профиль (можно не натощак): ОХС, ХС ЛНП, ХС ЛВП, ТГ, не-ЛВП.","Лп(а) — хотя бы раз в жизни у каждого взрослого.","Исключить вторичные причины: гипотиреоз, нефротический синдром, холестаз, препараты."],"treatment":[{"id":"start","h":"Начало терапии","items":[{"t":"Очень высокий риск и ХС ЛНП ≥ 1,8 — или высокий риск и ≥ 2,6 — начать лекарственную терапию.","cls":"I A"},{"t":"Статин высокой интенсивности до максимально переносимой дозы.","cls":"I A","dose":"аторвастатин 40–80 мг; розувастатин 20–40 мг"}]},{"id":"add","h":"Цель не достигнута","items":[{"t":"Добавить эзетимиб.","cls":"I B","dose":"10 мг/сут"},{"t":"Затем иPCSK9 (эволокумаб, алирокумаб); инклисиран — альтернатива.","cls":"I A","dose":"эволокумаб 140 мг раз в 2 недели; алирокумаб 75–150 мг раз в 2 недели; инклисиран 284 мг: 0, 3 мес, далее раз в 6 мес"},{"t":"Бемпедоевая кислота — добавка при недостижении цели.","cls":"IIa C","dose":"180 мг/сут"},{"t":"Непереносимость статинов — бемпедоевая кислота, эзетимиб, иPCSK9.","cls":"I B"}]},{"id":"acs","h":"ОКС","items":[{"t":"Статин высокой интенсивности в первые дни; если ХС ЛНП далёк от цели — сразу комбинация с эзетимибом.","cls":"I / IIa B"},{"t":"Если на статине до ОКС цель не была достигнута — интенсифицировать в госпитализацию.","cls":"I"}]},{"id":"tg","h":"Триглицериды","items":[{"t":"ТГ > 2,3 ммоль/л — статин как первая линия у высокого риска.","cls":"I"},{"t":"Высокий риск, ТГ 1,5–5,6 на статине — икозапент этил.","cls":"IIa B","dose":"2 г × 2/сут"},{"t":"ТГ > 8,5 ммоль/л при семейной хиломикронемии — воланесорсен.","cls":"IIa B","dose":"300 мг в неделю"}]}],"exam":["Липидный профиль, Лп(а)","АЛТ, КФК исходно (КФК — при мышечных симптомах), глюкоза/HbA1c, креатинин, ТТГ","SCORE2/SCORE2-OP у лиц без ССЗ и СД"],"followup":["ХС ЛНП через 4–8 (± 2) недель после начала или изменения терапии","После достижения цели — ежегодно","АЛТ — через 8–12 недель после старта статина"]},"87_5":{"id":"87_5","guideline":"AACE/ACE 2020 и Endocrine Society 2020: постменопаузальный остеопороз","org":"AACE/Endocrine Society","year":2020,"url":"https://doi.org/10.4158/GL-2020-0524SUPPL","diffs":["Пациентов делят на **высокий** и **очень высокий** риск переломов; при очень высоком — **сначала анаболики** (терипаратид, абалопаратид, ромосозумаб), затем антирезорбтивы.","Очень высокий риск: недавний перелом (< 12 мес), перелом на фоне лечения, множественные переломы, Т-критерий < −3,0, высокий риск падений, FRAX > 30% (основные) или > 4,5% (бедро).","Порог лечения по FRAX — **≥ 20% для основных переломов или ≥ 3% для бедра** (США; в КР — российский порог вмешательства по возрасту).","«Каникулы» от бисфосфонатов: пероральные — после 5 лет, золедроновая кислота — после 3 лет, если риск больше не высокий; деносумаб не прерывать без перехода на бисфосфонат.","Абалопаратид — нет в России."],"classification":{"theses":["Диагноз: Т-критерий ≤ −2,5, низкотравматичный перелом позвонка или бедра, либо остеопения с высоким FRAX.","Выбор первой терапии — по **категории риска**."],"blocks":[{"type":"tiles","title":"Категория риска","items":[{"big":"Высокий","label":"остеопороз без признаков очень высокого риска","tone":3,"go":{"title":"Высокий риск","g":["high"],"n":3}},{"big":"Очень высокий","label":"недавние или множественные переломы, Т < −3,0, FRAX > 30%","tone":4,"go":{"title":"Очень высокий риск","g":["vhigh"],"n":3}}]}]},"diagnosis":["DXA поясничного отдела и бедра; FRAX (с TBS при наличии).","Морфометрия позвонков (VFA или рентген) при снижении роста ≥ 4 см, кифозе, приёме ГКС.","Обследование на вторичные причины: кальций, фосфор, креатинин, ЩФ, 25(OH)D, ТТГ, ПТГ по показаниям, ОАК, электрофорез белков при подозрении на миелому."],"treatment":[{"id":"base","h":"Всем","items":[{"t":"Кальций с пищей 1000–1200 мг/сут (добавки — при недостатке), витамин D до 25(OH)D ≥ 30 нг/мл.","dose":"колекальциферол 1000–2000 МЕ/сут"},{"t":"Профилактика падений, физические упражнения с нагрузкой, отказ от курения, алкоголь ≤ 2 доз в день."}]},{"id":"high","h":"Высокий риск","items":[{"t":"Бисфосфонаты — первая линия.","cls":"1A","dose":"алендронат 70 мг 1 раз в неделю; ризедронат 35 мг в неделю; золедроновая кислота 5 мг в/в 1 раз в год"},{"t":"Деносумаб — альтернатива; не прерывать без перехода на бисфосфонат (риск множественных переломов позвонков).","cls":"1A","dose":"60 мг п/к раз в 6 месяцев"},{"t":"Ралоксифен — при риске рака молочной железы и низком риске переломов бедра.","dose":"60 мг/сут"}]},{"id":"vhigh","h":"Очень высокий риск","items":[{"t":"Анаболик первым: терипаратид до 2 лет или ромосозумаб 12 месяцев (не при ИМ/инсульте за последний год).","cls":"1A","dose":"терипаратид 20 мкг п/к ежедневно; ромосозумаб 210 мг п/к ежемесячно"},{"t":"После анаболика — обязательно антирезорбтив (бисфосфонат или деносумаб).","cls":"1A"},{"t":"Альтернатива — деносумаб или золедроновая кислота."}]}],"exam":["DXA, FRAX","Кальций, фосфор, креатинин, ЩФ, 25(OH)D, ТТГ; ПТГ по показаниям","Морфометрия позвонков по показаниям"],"followup":["DXA каждые 1–2 года до стабилизации, затем реже","Переоценка риска через 3–5 лет бисфосфонатов — решение о «каникулах»","Стоматологический осмотр до старта антирезорбтивов (риск остеонекроза челюсти)"]}};
